<script setup>
import {ref,onMounted} from 'vue';import {api,jsonBody} from '../api';import {auth,hasPermission} from '../auth';import {showConfirm} from '../uiDialogs';
const legacyOrders=ref([]);
const cancellations=ref([]),requests=ref([]),note=ref(''),temporary=ref(''),error=ref(''),busy=ref(false);
async function load(){try{if(auth.user?.admin)legacyOrders.value=await api('/rankings/admin/aftercare/legacy-orders');if(hasPermission('rankings.cancellations.read'))cancellations.value=await api('/rankings/admin/aftercare/cancellations');if(hasPermission('rankings.recovery.read'))requests.value=await api('/rankings/admin/aftercare/recoveries');}catch(e){error.value=e.message;}}
async function act(path,body,message){if(busy.value)return;if(!await showConfirm(message))return;busy.value=true;error.value='';try{await api('/rankings/admin/aftercare/'+path,{method:'POST',body:jsonBody(body)});temporary.value='';await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function fulfill(id){if(!await showConfirm('确认已发放这笔历史订单的奖品？'))return;busy.value=true;error.value='';try{await api('/rankings/admin/redemptions/'+id+'/fulfillment',{method:'PATCH',body:jsonBody({fulfilled:true})});await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(load);
</script>
<template><section class="aftercare"><p v-if="error" class="notice notice-error" role="alert">{{error}}</p><label>处理说明<input v-model="note" maxlength="500" placeholder="核实身份或取消兑换的处理依据"></label><section v-if="hasPermission('rankings.cancellations.read')"><h2>取消兑换申请</h2><p>仅未发放订单可取消；同意后退还积分和库存，已删除的奖品不会重新上架。</p><div class="scroll"><table><thead><tr><th>学员 / 商品</th><th>申请原因</th><th>状态</th><th>处理</th></tr></thead><tbody><tr v-for="c in cancellations" :key="c.redemption_id"><td>{{c.student_name}} · {{c.reward_name}}<small v-if="auth.user?.admin">原老师：{{c.owner_username}}</small><small>返还 {{c.points_spent}} 积分</small></td><td>{{c.reason}}</td><td>{{c.status}}</td><td><div v-if="c.status==='CANCEL_REQUESTED'&&hasPermission('rankings.cancellations.decide')" class="button-row"><button class="button button-primary" :disabled="busy||!note.trim()" @click="act(`cancellations/${c.redemption_id}/decision`,{approved:true,reason:note},'同意取消，退还积分并恢复库存？')">同意退款</button><button class="button button-quiet" :disabled="busy||!note.trim()" @click="act(`cancellations/${c.redemption_id}/decision`,{approved:false,reason:note},'拒绝取消申请并恢复待发放？')">拒绝</button></div><span v-else>{{c.decision_note||'暂无可用操作'}}</span></td></tr></tbody></table></div></section><section v-if="hasPermission('rankings.recovery.read')"><h2>账号找回申请</h2><p>老师先核实身份，最高管理员再设置临时密码。重置会使旧登录失效。</p><label v-if="auth.user?.admin">临时密码<input v-model="temporary" type="password" autocomplete="new-password" minlength="6" maxlength="72" placeholder="处理前填写临时密码"></label><div class="scroll"><table><thead><tr><th>学员 / 老师</th><th>原因</th><th>状态</th><th>处理</th></tr></thead><tbody><tr v-for="q in requests" :key="q.id"><td>{{q.student_name}} · {{q.student_id}}<small>{{q.owner_username}}</small></td><td>{{q.reason}}</td><td>{{q.status}}</td><td><div class="button-row" v-if="q.status==='PENDING_VERIFY'&&hasPermission('rankings.recovery.verify')&&q.owner_username===auth.user?.username"><button class="button button-primary" :disabled="busy||!note.trim()" @click="act(`recoveries/${q.id}/verify`,{approved:true,reason:note},'确认已核实该学员身份？')">核实通过</button><button class="button button-quiet" :disabled="busy||!note.trim()" @click="act(`recoveries/${q.id}/verify`,{approved:false,reason:note},'拒绝本次申请？')">拒绝</button></div><button v-if="q.status==='VERIFIED'&&auth.user?.admin" class="button button-primary" :disabled="busy||temporary.length<6" @click="act(`recoveries/${q.id}/resolve`,{password:temporary},'重置密码并使旧登录失效？请将临时密码告知已核实身份的学生。')">重置临时密码</button></td></tr></tbody></table></div></section><section v-if="auth.user?.admin"><h2>跨老师历史订单处理</h2><p>最高管理员可处理离职老师保留的订单；退款进入学生当前账户。最近200笔跨老师订单：</p><div class="scroll"><table><thead><tr><th>原老师</th><th>学生 / 奖品</th><th>状态</th><th>处理</th></tr></thead><tbody><tr v-for="o in legacyOrders" :key="o.id"><td>{{o.owner_username}}</td><td>{{o.student_name}} · {{o.reward_name}}</td><td>{{o.status}}</td><td><button v-if="o.status==='PENDING'" class="button button-primary" :disabled="busy" @click="fulfill(o.id)">确认已发放</button><span v-else>{{o.status==='CANCEL_REQUESTED'?'请在上方审批取消申请':'无需处理'}}</span></td></tr></tbody></table></div></section></section></template>
<style scoped>.aftercare{padding:20px;background:white;border:1px solid #d8e0e3;border-radius:10px;display:grid;gap:24px;min-width:0}.aftercare>section{min-width:0}.aftercare h2{font-size:18px}.aftercare p,.aftercare small{color:#637984}.aftercare small{display:block}.aftercare label{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.aftercare input{padding:9px;border:1px solid #d8e0e3;border-radius:6px;min-width:0;flex:1 1 180px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #e3e9eb;text-align:left;min-width:100px}</style>
